import java.util.function.Supplier;

/**
 * Starting with the premise that the objects used by the background thread must not be created by (or visible
 * to) the application thread, {@code CachedSupplier} defers creation of such an object until the first call to
 * {@link #get()}, which then caches it for all subsequent calls. Subclasses implement {@link #create()} to build
 * the object.
