        properties.put(ConsumerConfig.VALUE_DESERIALIZER_CLASS_CONFIG, StringDeserializer.class.getName());

        if (withGroupId)
            properties.put(ConsumerConfig.GROUP_ID_CONFIG, "group");

        return new ConsumerConfig(properties);
    }

