    private static final FindCoordinatorRequest.CoordinatorType GROUP = FindCoordinatorRequest.CoordinatorType.GROUP;
    private static final String GROUP_TYPE = Collections.singletonList(GROUP).stream().map(Enum::name).collect(Collectors.joining());
}

